/*
 * fast_eig.c
 *
 * Fast computation of the dominant eigenpair (largest magnitude eigenvalue
 * and a corresponding eigenvector) of a real n x n matrix (n <= 10).
 *
 * Strategy:
 *   1. Characteristic polynomial via power sums (traces of A^k) + Newton
 *      identities.  n matrix products (cheap for n <= 10).
 *   2. All roots via Durand-Kerner (Weierstrass) simultaneous iteration,
 *      started on the Gershgorin radius circle, then Newton polish.
 *      This handles real and complex-conjugate dominant eigenvalues.
 *   3. Dominant root = root with largest magnitude.
 *   4. Eigenvector via a few inverse-iteration steps:
 *        - real lambda:     solve (A - (lambda-eps) I) x = b   (LU + backsub)
 *        - complex lambda:  solve 2n x 2n real system
 *                           [A-aI,  bI; -bI, A-aI] x = b  +  eps*I  regularization
 *      One application of the (regularized) inverse already projects onto the
 *      null space since eps << eigenvalue gaps; a few more iterations refine.
 *   5. Internal verification of  ||A v - lambda v||  before reporting success.
 *
 * The entry point returns 0 (failure) on any numerical difficulty so the
 * Python caller can fall back to a reference implementation.
 */

#include <math.h>
#include <string.h>

#define MAXN 10

typedef struct { double r, i; } cd;

static inline cd cd_mul(cd a, cd b) {
    cd c;
    c.r = a.r * b.r - a.i * b.i;
    c.i = a.r * b.i + a.i * b.r;
    return c;
}

static inline double cd_abs(cd a) { return sqrt(a.r * a.r + a.i * a.i); }

/* p(z) = z^n + c1 z^{n-1} + ... + c_{n-1} z + c_n  (Horner) */
static cd poly_eval(int n, const double c[], cd z) {
    cd res;
    res.r = 1.0; res.i = 0.0;
    for (int k = 1; k <= n; k++) {
        res = cd_mul(res, z);
        res.r += c[k];
    }
    return res;
}

/* p'(z) via Horner on the derivative coefficients */
static cd poly_deriv(int n, const double c[], cd z) {
    cd res;
    res.r = 0.0; res.i = 0.0;
    for (int j = 0; j <= n - 1; j++) {
        double coef = (double)(n - j) * (j == 0 ? 1.0 : c[j]);
        res = cd_mul(res, z);
        res.r += coef;
    }
    return res;
}

/* Durand-Kerner simultaneous iteration on the monic polynomial.
 * z[] (n entries) in/out. Returns 1 if it finished without pathology. */
static int durand_kerner(int n, const double c[], cd z[], int maxit, double scale) {
    double brk = 1e-12;
    for (int it = 0; it < maxit; it++) {
        cd zn[MAXN];
        double maxch = 0.0;
        for (int i = 0; i < n; i++) {
            cd f = poly_eval(n, c, z[i]);
            cd prod;
            prod.r = 1.0; prod.i = 0.0;
            for (int j = 0; j < n; j++) {
                if (j == i) continue;
                cd d;
                d.r = z[i].r - z[j].r;
                d.i = z[i].i - z[j].i;
                prod = cd_mul(prod, d);
            }
            double pd = prod.r * prod.r + prod.i * prod.i;
            if (pd < 1e-24) return 0;          /* two iterates collided */
            double st_r = (f.r * prod.r + f.i * prod.i) / pd;
            double st_i = (f.i * prod.r - f.r * prod.i) / pd;
            if (!isfinite(st_r) || !isfinite(st_i)) return 0;
            double zr = z[i].r - st_r;
            double zi = z[i].i - st_i;
            if (!isfinite(zr) || !isfinite(zi)) return 0;
            double ch = sqrt(st_r * st_r + st_i * st_i);
            if (ch > maxch) maxch = ch;
            zn[i].r = zr; zn[i].i = zi;
        }
        for (int i = 0; i < n; i++) z[i] = zn[i];
        if (maxch < brk * scale) break;
    }
    return 1;
}

/* Newton polish of one root; returns 1 if residual check passes. */
static int newton_polish(int n, const double c[], cd *z, double scale) {
    cd cur = *z;
    for (int it = 0; it < 12; it++) {
        cd f = poly_eval(n, c, cur);
        cd fp = poly_deriv(n, c, cur);
        double fd = fp.r * fp.r + fp.i * fp.i;
        if (fd < 1e-300) break;
        double st_r = (f.r * fp.r + f.i * fp.i) / fd;
        double st_i = (f.i * fp.r - f.r * fp.i) / fd;
        if (!isfinite(st_r) || !isfinite(st_i)) break;
        double nr = cur.r - st_r;
        double ni = cur.i - st_i;
        if (!isfinite(nr) || !isfinite(ni)) break;
        cur.r = nr; cur.i = ni;
        if (sqrt(st_r * st_r + st_i * st_i) <= 1e-15 * (sqrt(nr * nr + ni * ni) + 1e-300))
            break;
    }
    *z = cur;
    cd fv = poly_eval(n, c, cur);
    return (fv.r * fv.r + fv.i * fv.i) <= 1e-26 * scale * scale;
}

/* LU factorization with partial pivoting, row-major n x n (n <= 20).
 * M is overwritten. Returns 0 if (numerically) singular. */
static int lu_factor(double M[], int n, int piv[]) {
    for (int k = 0; k < n; k++) {
        int pk = k;
        double mx = fabs(M[k * n + k]);
        for (int i = k + 1; i < n; i++) {
            double v = fabs(M[i * n + k]);
            if (v > mx) { mx = v; pk = i; }
        }
        if (mx < 1e-30) return 0;
        if (pk != k) {
            for (int j = k; j < n; j++) {
                double t = M[k * n + j];
                M[k * n + j] = M[pk * n + j];
                M[pk * n + j] = t;
            }
        }
        piv[k] = pk;
        for (int i = k + 1; i < n; i++) {
            double f = M[i * n + k] / M[k * n + k];
            M[i * n + k] = f;
            for (int j = k + 1; j < n; j++)
                M[i * n + j] -= f * M[k * n + j];
        }
    }
    return 1;
}

/* Solve (L U) x = b for the factored system. x is output. */
static void lu_solve(const double M[], int n, const int piv[], const double b[], double x[]) {
    /* y = P b, forward substitution with unit-diagonal L */
    for (int k = 0; k < n; k++) {
        double y = b[piv[k]];
        for (int i = 0; i < k; i++) y -= M[k * n + i] * x[i];
        x[k] = y;
    }
    /* back substitution with U */
    for (int k = n - 1; k >= 0; k--) {
        double y = x[k];
        for (int i = k + 1; i < n; i++) y -= M[k * n + i] * x[i];
        x[k] = y / M[k * n + k];
    }
}

/* Eigenvector for a real eigenvalue l: inverse iteration on A - (l - eps) I.
 * Tries every canonical basis vector as the start (cheap for n <= 10) and
 * keeps the result with the largest norm (best null-space component), then
 * refines with 3 more iterations. */
static int eigvec_real(int n, const double a[], double l, double v[]) {
    double B[MAXN * MAXN];
    int piv[MAXN];
    double x[MAXN], xbest[MAXN];
    double eps = 1e-7 * fmax(1.0, fabs(l));
    double sh = l - eps;
    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++)
            B[i * n + j] = a[i * n + j] - ((i == j) ? sh : 0.0);
    if (!lu_factor(B, n, piv)) return 0;
    double bestnm = 0.0;
    for (int s = 0; s < n; s++) {
        for (int i = 0; i < n; i++) x[i] = (i == s) ? 1.0 : 0.0;
        lu_solve(B, n, piv, x, x);
        double nm2 = 0.0;
        for (int i = 0; i < n; i++) nm2 += x[i] * x[i];
        if (!isfinite(nm2)) return 0;
        if (nm2 > bestnm) {
            bestnm = nm2;
            for (int i = 0; i < n; i++) xbest[i] = x[i];
        }
    }
    if (bestnm < 1e-200) return 0;
    double inv = 1.0 / sqrt(bestnm);
    for (int i = 0; i < n; i++) xbest[i] *= inv;
    for (int it = 0; it < 3; it++) {
        lu_solve(B, n, piv, xbest, x);
        double nm2 = 0.0;
        for (int i = 0; i < n; i++) nm2 += x[i] * x[i];
        if (!isfinite(nm2) || nm2 < 1e-200) return 0;
        inv = 1.0 / sqrt(nm2);
        for (int i = 0; i < n; i++) xbest[i] = x[i] * inv;
    }
    for (int i = 0; i < n; i++) v[i] = xbest[i];
    return 1;
}

/* Eigenvector for complex eigenvalue l = a + b i (b != 0).
 * Null space of  [A-aI,  bI; -bI, A-aI]  is 2-dim; any nonzero vector
 * [u; v] in it gives eigenvector u + i v. */
static int eigvec_complex(int n, const double a[], double ar, double ai, double vr[], double vi[]) {
    int m = 2 * n;
    double M[2 * MAXN * 2 * MAXN];
    int piv[2 * MAXN];
    double x[2 * MAXN], xbest[2 * MAXN];
    double eps = 1e-7 * fmax(1.0, sqrt(ar * ar + ai * ai));
    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++) {
            M[i * m + j] = a[i * n + j] - ((i == j) ? ar : 0.0);
            M[i * m + j + n] = ((i == j) ? ai : 0.0);
            M[(i + n) * m + j] = -((i == j) ? ai : 0.0);
            M[(i + n) * m + j + n] = a[i * n + j] - ((i == j) ? ar : 0.0);
        }
    for (int i = 0; i < m; i++) M[i * m + i] += eps;
    if (!lu_factor(M, m, piv)) return 0;
    double bestnm = 0.0;
    for (int s = 0; s < m; s++) {
        for (int i = 0; i < m; i++) x[i] = (i == s) ? 1.0 : 0.0;
        lu_solve(M, m, piv, x, x);
        double nm2 = 0.0;
        for (int i = 0; i < m; i++) nm2 += x[i] * x[i];
        if (!isfinite(nm2)) return 0;
        if (nm2 > bestnm) {
            bestnm = nm2;
            for (int i = 0; i < m; i++) xbest[i] = x[i];
        }
    }
    if (bestnm < 1e-200) return 0;
    double inv = 1.0 / sqrt(bestnm);
    for (int i = 0; i < m; i++) xbest[i] *= inv;
    for (int it = 0; it < 3; it++) {
        lu_solve(M, m, piv, xbest, x);
        double nm2 = 0.0;
        for (int i = 0; i < m; i++) nm2 += x[i] * x[i];
        if (!isfinite(nm2) || nm2 < 1e-200) return 0;
        inv = 1.0 / sqrt(nm2);
        for (int i = 0; i < m; i++) xbest[i] = x[i] * inv;
    }
    for (int i = 0; i < n; i++) { vr[i] = xbest[i]; vi[i] = xbest[i + n]; }
    return 1;
}

/*
 * Main entry point.
 *   n        : matrix size (1..10)
 *   a        : input matrix, row-major n x n, float64
 *   lam_out  : 2 doubles (re, im) of the dominant eigenvalue
 *   vec_out  : 2n doubles (re part n, then im part n) of the eigenvector
 * Returns 1 on success (residual verified), 0 on any failure.
 */
int fast_dominant_eig(int n, const double a[], double lam_out[], double vec_out[]) {
    if (n < 1 || n > MAXN) return 0;
    for (int i = 0; i < n * n; i++)
        if (!isfinite(a[i])) return 0;

    if (n == 1) {
        lam_out[0] = a[0]; lam_out[1] = 0.0;
        vec_out[0] = 1.0; vec_out[1] = 0.0;
        return 1;
    }

    /* ---- 1. power sums p_k = tr(A^k) ---- */
    double P[MAXN * MAXN], Q[MAXN * MAXN];
    double p[MAXN + 1];
    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++)
            P[i * n + j] = (i == j) ? 1.0 : 0.0;
    p[0] = (double)n;
    for (int k = 1; k <= n; k++) {
        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++)
                Q[i * n + j] = 0.0;
        for (int i = 0; i < n; i++)
            for (int t = 0; t < n; t++) {
                double at = a[i * n + t];
                if (at == 0.0) continue;
                for (int j = 0; j < n; j++)
                    Q[i * n + j] += at * P[t * n + j];
            }
        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++)
                P[i * n + j] = Q[i * n + j];
        double tr = 0.0;
        for (int i = 0; i < n; i++) tr += P[i * n + i];
        if (!isfinite(tr)) return 0;
        p[k] = tr;
    }

    /* ---- 2. Newton identities -> elementary symmetric polys -> coeffs ---- */
    double e[MAXN + 1], c[MAXN + 1];
    e[0] = 1.0;
    for (int k = 1; k <= n; k++) {
        double s = 0.0;
        for (int i = 1; i <= k; i++) {
            double sgn = (i & 1) ? 1.0 : -1.0;   /* (-1)^(i-1) */
            s += sgn * e[k - i] * p[i];
        }
        e[k] = s / (double)k;
    }
    c[0] = 1.0;
    for (int k = 1; k <= n; k++)
        c[k] = ((k & 1) ? -1.0 : 1.0) * e[k];    /* c_k = (-1)^k e_k */
    for (int k = 0; k <= n; k++)
        if (!isfinite(c[k])) return 0;

    /* ---- 3. Gershgorin radius (bounds |lambda| for all eigenvalues) ---- */
    double R = 0.0;
    for (int i = 0; i < n; i++) {
        double s = fabs(a[i * n + i]);
        for (int j = 0; j < n; j++)
            if (j != i) s += fabs(a[i * n + j]);
        if (s > R) R = s;
    }
    if (R < 1e-8) R = 1e-8;

    /* polynomial scale for convergence tests */
    double scale = 0.0;
    for (int k = 0; k <= n; k++) {
        double ck = (k == 0) ? 1.0 : c[k];
        double pw = 1.0;
        for (int t = 0; t < n - k; t++) pw *= R;
        scale += fabs(ck) * pw;
    }
    if (scale < 1e-300) scale = 1e-300;

    /* ---- 4. Durand-Kerner from the Gershgorin circle ---- */
    cd z[MAXN];
    for (int i = 0; i < n; i++) {
        double ang = 2.0 * M_PI * (double)i / (double)n;
        z[i].r = R * cos(ang);
        z[i].i = R * sin(ang);
    }
    if (!durand_kerner(n, c, z, 100, scale)) return 0;

    /* ---- 5. Newton polish + verification of every root ---- */
    for (int i = 0; i < n; i++)
        if (!newton_polish(n, c, &z[i], scale)) return 0;

    /* ---- 6. pick dominant root ---- */
    int bi = 0;
    double bm2 = z[0].r * z[0].r + z[0].i * z[0].i;
    for (int i = 1; i < n; i++) {
        double m2 = z[i].r * z[i].r + z[i].i * z[i].i;
        if (m2 > bm2) { bm2 = m2; bi = i; }
    }
    cd lam = z[bi];
    double lam_abs = sqrt(bm2);

    /* ---- 7. eigenvector by inverse iteration ---- */
    double vr[MAXN], vi[MAXN];
    int ok;
    double tol = 1e-7 * fmax(1.0, lam_abs);
    if (fabs(lam.i) <= tol) {
        ok = eigvec_real(n, a, lam.r, vr);
        for (int i = 0; i < n; i++) vi[i] = 0.0;
    } else {
        ok = eigvec_complex(n, a, lam.r, lam.i, vr, vi);
    }
    if (!ok) return 0;

    /* ---- 8. residual verification on the original matrix ---- */
    double r2 = 0.0, vn2 = 0.0;
    for (int i = 0; i < n; i++) {
        vn2 += vr[i] * vr[i] + vi[i] * vi[i];
        double sr = lam.r * vr[i] - lam.i * vi[i];
        double si = lam.r * vi[i] + lam.i * vr[i];
        for (int j = 0; j < n; j++) {
            sr += a[i * n + j] * vr[j];
            si += a[i * n + j] * vi[j];
        }
        r2 += sr * sr + si * si;
    }
    if (!isfinite(r2) || !isfinite(vn2) || vn2 < 1e-16) return 0;
    double thr = 1e-6 * sqrt(lam_abs * lam_abs + 1.0) * sqrt(vn2);
    if (sqrt(r2) > thr) return 0;

    /* normalize eigenvector to unit norm */
    double inv = 1.0 / sqrt(vn2);
    for (int i = 0; i < n; i++) { vr[i] *= inv; vi[i] *= inv; }

    lam_out[0] = lam.r;
    lam_out[1] = lam.i;
    for (int i = 0; i < n; i++) {
        vec_out[i] = vr[i];
        vec_out[n + i] = vi[i];
    }
    return 1;
}

