#include <stdio.h>
#include <math.h>
#include <stdlib.h>

typedef struct { double r, i; } cd;

/* paste of functions from fast_eig.c (copy) */
#define MAXN 10
static inline cd cd_mul(cd a, cd b){ cd c; c.r=a.r*b.r-a.i*b.i; c.i=a.r*b.i+a.i*b.r; return c; }
static cd poly_eval(int n, const double c[], cd z){ cd res={1.0,0.0}; for(int k=1;k<=n;k++){ res=cd_mul(res,z); res.r+=c[k]; } return res; }
static cd poly_deriv(int n, const double c[], cd z){ cd res={0.0,0.0}; for(int j=0;j<=n-1;j++){ double coef=(double)(n-j)*(j==0?1.0:c[j]); res=cd_mul(res,z); res.r+=coef; } return res; }
static int durand_kerner(int n, const double c[], cd z[], int maxit, double scale){
    for(int it=0; it<maxit; it++){ cd zn[MAXN]; double maxch=0.0;
        for(int i=0;i<n;i++){ cd f=poly_eval(n,c,z[i]); cd prod={1.0,0.0};
            for(int j=0;j<n;j++){ if(j==i)continue; cd d={z[i].r-z[j].r,z[i].i-z[j].i}; prod=cd_mul(prod,d);}
            double pd=prod.r*prod.r+prod.i*prod.i; if(pd<1e-24)return -1;
            double st_r=(f.r*prod.r+f.i*prod.i)/pd, st_i=(f.i*prod.r-f.r*prod.i)/pd;
            if(!isfinite(st_r)||!isfinite(st_i))return -2;
            double zr=z[i].r-st_r, zi=z[i].i-st_i; if(!isfinite(zr)||!isfinite(zi))return -3;
            double ch=sqrt(st_r*st_r+st_i*st_i); if(ch>maxch)maxch=ch; zn[i].r=zr; zn[i].i=zi; }
        for(int i=0;i<n;i++)z[i]=zn[i];
        if(maxch<1e-12*scale)break; }
    return 1; }

int main(int argc, char** argv){
    int n = 5;
    double A[MAXN*MAXN];
    srand(1);
    for(int i=0;i<n*n;i++) A[i] = (double)rand()/RAND_MAX*4-2;
    /* power sums */
    double P[MAXN*MAXN], Q[MAXN*MAXN], p[MAXN+1];
    for(int i=0;i<n;i++)for(int j=0;j<n;j++)P[i*n+j]=(i==j)?1.0:0.0;
    p[0]=n;
    for(int k=1;k<=n;k++){
        for(int i=0;i<n;i++)for(int j=0;j<n;j++)Q[i*n+j]=0.0;
        for(int i=0;i<n;i++)for(int t=0;t<n;t++){ double at=A[i*n+t]; if(at==0.0)continue;
            for(int j=0;j<n;j++)Q[i*n+j]+=at*P[t*n+j]; }
        for(int i=0;i<n;i++)for(int j=0;j<n;j++)P[i*n+j]=Q[i*n+j];
        double tr=0; for(int i=0;i<n;i++)tr+=P[i*n+i]; p[k]=tr;
    }
