        for(int it=0;it<20;it++){ cd f=poly_eval(n,c,cur); cd fp=poly_deriv(n,c,cur);
            double fd=fp.r*fp.r+fp.i*fp.i; if(fd<1e-300)break;
            double st_r=(f.r*fp.r+f.i*fp.i)/fd, st_i=(f.i*fp.r-f.r*fp.i)/fd;
            if(!isfinite(st_r)||!isfinite(st_i))break;
            cur.r-=st_r; cur.i-=st_i;
            if(sqrt(st_r*st_r+st_i*st_i)<=1e-15*(sqrt(cur.r*cur.r+cur.i*cur.i)+1e-300))break; }
        z[i]=cur;
        cd fv=poly_eval(n,c,z[i]);
        if(fv.r*fv.r+fv.i*fv.i > 1e-26*scale*scale) return 0; }
    /* distinctness + product */
    for(int i=0;i<n;i++)for(int j=i+1;j<n;j++){
        double dr=z[i].r-z[j].r, di=z[i].i-z[j].i;
        if(sqrt(dr*dr+di*di) < 1e-6*fmax(1.0,fmax(sqrt(z[i].r*z[i].r+z[i].i*z[i].i),sqrt(z[j].r*z[j].r+z[j].i*z[j].i)))) return 0; }
    cd p={1.0,0.0}; for(int i=0;i<n;i++)p=cd_mul(p,z[i]);
    double ref=(n&1)?-0:0; (void)ref;
    double cn=(n&1)?-c[n]:c[n];
    if(fabs(sqrt(p.r*p.r+p.i*p.i)-fabs(cn)) > 1e-6*fmax(1.0,fabs(cn))) return 0;
    return 1; }

/* Newton + deflation */
static int newton_deflate(int n, const double c[], double R, double scale, cd roots[]){
    double coef[MAXN+1];
    for(int k=0;k<=n;k++) coef[k]=c[k];
    for(int k=0;k<n;k++){
        int found=0;
        for(int attempt=0; attempt<2*n && !found; attempt++){
            double ang = 2.0*M_PI*((double)attempt+0.5)/(double)n + 0.3*M_PI*((double)k/(double)n);
            cd z={R*cos(ang), R*sin(ang)};
            cd cur=z;
            for(int it=0;it<40;it++){
                /* evaluate coef (degree n-k) */
                int deg = n-k;
                cd f={1.0,0.0};
                for(int j=1;j<=deg;j++){ f=cd_mul(f,cur); f.r+=coef[j]; }
                cd fp={0.0,0.0};
                for(int j=0;j<=deg-1;j++){ double cf=(double)(deg-j)*(j==0?1.0:coef[j]); fp=cd_mul(fp,cur); fp.r+=cf; }
                double fd=fp.r*fp.r+fp.i*fp.i; if(fd<1e-300)break;
                double st_r=(f.r*fp.r+f.i*fp.i)/fd, st_i=(f.i*fp.r-f.r*fp.i)/fd;
                if(!isfinite(st_r)||!isfinite(st_i))break;
                cur.r-=st_r; cur.i-=st_i;
                if(sqrt(st_r*st_r+st_i*st_i)<=1e-15*(sqrt(cur.r*cur.r+cur.i*cur.i)+1e-300))break;
            }
            /* check convergence: |f(cur)| small relative to scale */
            int deg = n-k;
            cd f={1.0,0.0};
            for(int j=1;j<=deg;j++){ f=cd_mul(f,cur); f.r+=coef[j]; }
            if(f.r*f.r+f.i*f.i > 1e-24*scale*scale) continue;
            /* distinct from previous roots */
            int dup=0;
            for(int q=0;q<k;q++){ double dr=cur.r-roots[q].r, di=cur.i-roots[q].i;
                if(sqrt(dr*dr+di*di) < 1e-5*fmax(1.0,fmax(sqrt(cur.r*cur.r+cur.i*cur.i),sqrt(roots[q].r*roots[q].r+roots[q].i*roots[q].i)))){ dup=1; break; } }
            if(dup) continue;
            roots[k]=cur; found=1;
            /* deflate: coef /= (z - cur)  (synthetic division, monic divisor) */
            double nc[MAXN+1]; nc[0]=1.0;
            for(int j=1;j<=deg;j++) nc[j]=coef[j] - (-cur.r)*nc[j-1] - (0.0)*0; /* placeholder, do proper below */
            /* proper synthetic division of monic poly coef (deg) by (z - cur):
               q(x) = x^{deg-1} + q1 x^{deg-2}+...,  coef[j] = q[j-1] + cur.r*q[j-1] - cur.i*q[j-1]... do complex:
               coef = (z - cur) * q  =>  q[0]=1; q[j] = coef[j] - cur*q[j-1]  (complex) */
            cd q[MAXN+1]; q[0]={1.0,0.0};
            int okq=1;
            for(int j=1;j<=deg;j++){
                q[j]= (cd){coef[j]-q[j-1].r*0.0, 0.0}; /* coef[j] is real */
                q[j].r = coef[j] - q[j-1].r*cur.r + q[j-1].i*cur.i;
                q[j].i = 0.0 - q[j-1].i*cur.r - q[j-1].r*cur.i;
                /* check consistency: (z-cur)q should reproduce; verify last remainder */
            }
            /* remainder check */
            double rem_r = coef[deg] - (q[deg-1].r*cur.r - q[deg-1].i*cur.i);
            double rem_i = 0.0 - (q[deg-1].i*cur.r + q[deg-1].r*cur.i);
            if(rem_r*rem_r+rem_i*rem_i > 1e-20*scale*scale){ okq=0; }
            if(!okq) continue;
            coef[0]=1.0;
            for(int j=1;j<deg;j++) coef[j]=q[j].r; /* imag should be ~0 */
            for(int j=0;j<deg;j++){
                if(fabs(q[j].i) > 1e-10*fmax(1.0,fabs(q[j].r))) okq=0;
            }
            if(!okq) continue;
        }
        if(!found) return 0;
    }
    return 1; }

int main(void){
    srand(777);
    for (int n = 3; n <= 4; n++) {
        int failA=0, failB=0, failC=0, tot=2000;
        for(int t=0;t<tot;t++){
            double A[MAXN*MAXN]; for(int i=0;i<n*n;i++) A[i]=((double)rand()/RAND_MAX)*4.0-2.0;
            /* power sums + newton identities */
            double P[MAXN*MAXN], Q[MAXN*MAXN], p[MAXN+1];
            for(int i=0;i<n;i++)for(int j=0;j<n;j++)P[i*n+j]=(i==j)?1.0:0.0;
            p[0]=n;
            for(int k=1;k<=n;k++){
                for(int i=0;i<n;i++)for(int j=0;j<n;j++)Q[i*n+j]=0.0;
                for(int i=0;i<n;i++)for(int tt=0;tt<n;tt++){ double at=A[i*n+tt]; if(at==0.0)continue;
                    for(int j=0;j<n;j++)Q[i*n+j]+=at*P[tt*n+j]; }
                for(int i=0;i<n;i++)for(int j=0;j<n;j++)P[i*n+j]=Q[i*n+j];
                double tr=0; for(int i=0;i<n;i++)tr+=P[i*n+i]; p[k]=tr; }
            double e[MAXN+1], c[MAXN+1]; e[0]=1.0;
            for(int k=1;k<=n;k++){ double s=0; for(int i=1;i<=k;i++){ double sgn=(i&1)?1.0:-1.0; s+=sgn*e[k-i]*p[i]; } e[k]=s/k; }
            c[0]=1.0; for(int k=1;k<=n;k++)c[k]=((k&1)?-1.0:1.0)*e[k];
            double R=0;
            for(int i=0;i<n;i++){ double s=fabs(A[i*n+i]); for(int j=0;j<n;j++)if(j!=i)s+=fabs(A[i*n+j]); if(s>R)R=s; }
            if(R<1e-8)R=1e-8;
            double scale=0; for(int k=0;k<=n;k++){ double ck=(k==0)?1.0:c[k]; double pw=1; for(int tt=0;tt<n-k;tt++)pw*=R; scale+=fabs(ck)*pw; }
            /* variant A: current (half-step + tiny shear) */
            cd zA[MAXN]; for(int i=0;i<n;i++){ double ang=2*M_PI*((double)i+0.5)/n + 1e-6*((double)i-0.5*(n-1)); zA[i].r=R*cos(ang); zA[i].i=R*sin(ang); }
            int okA = (dk_run(n,c,zA,100,scale)>0) && polish_all(n,c,zA,scale);
            /* variant B: radius ramp + half-step */
            cd zB[MAXN]; for(int i=0;i<n;i++){ double ang=2*M_PI*((double)i+0.5)/n; double rr=R*(1.0+0.4*((double)i/(double)(n-1)-0.5)); zB[i].r=rr*cos(ang); zB[i].i=rr*sin(ang); }
            int okB = (dk_run(n,c,zB,100,scale)>0) && polish_all(n,c,zB,scale);
            /* variant C: newton deflation */
            cd zC[MAXN]; int okC = newton_deflate(n,c,R,scale,zC);
            if(!okA)failA++; if(!okB)failB++; if(!okC)failC++;
        }
        printf("n=%d: failA(current)=%d  failB(ramp)=%d  failC(newton-deflate)=%d  of %d\n", n, failA, failB, failC, tot);
    }
    return 0;
}
