#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#define MAXN 10
typedef struct { double r, i; } cd;
static inline cd cd_mul(cd a, cd b){ cd c; c.r=a.r*b.r-a.i*b.i; c.i=a.r*b.i+a.i*b.r; return c; }
static double cd_abs(cd a){ return sqrt(a.r*a.r+a.i*a.i); }

static cd poly_eval(int n, const double c[], cd z){ cd res={1.0,0.0}; for(int k=1;k<=n;k++){ res=cd_mul(res,z); res.r+=c[k]; } return res; }
static cd poly_deriv(int n, const double c[], cd z){ cd res={0.0,0.0}; for(int j=0;j<=n-1;j++){ double coef=(double)(n-j)*(j==0?1.0:c[j]); res=cd_mul(res,z); res.r+=coef; } return res; }

static int dk_run(int n, const double c[], cd z[], int maxit, double scale){
    for(int it=0; it<maxit; it++){
        cd zn[MAXN]; double maxch=0.0;
        for(int i=0;i<n;i++){
            cd f=poly_eval(n,c,z[i]);
            cd prod={1.0,0.0};
            for(int j=0;j<n;j++){ if(j==i)continue; prod=cd_mul(prod, (cd){z[i].r-z[j].r, z[i].i-z[j].i}); }
            double pd=prod.r*prod.r+prod.i*prod.i; if(pd<1e-24)return -1;
            double st_r=(f.r*prod.r+f.i*prod.i)/pd, st_i=(f.i*prod.r-f.r*prod.i)/pd;
            if(!isfinite(st_r)||!isfinite(st_i))return -2;
            z[i].r-=st_r; z[i].i-=st_i;
            double ch=sqrt(st_r*st_r+st_i*st_i); if(ch>maxch)maxch=ch;
            zn[i]=z[i];
        }
        for(int i=0;i<n;i++)z[i]=zn[i];
        if(maxch<1e-12*scale)break;
    }
    return 1;
}

static int polish_all(int n, const double c[], cd z[], double scale){
    for(int i=0;i<n;i++){
        cd cur=z[i];
        for(int it=0;it<20;it++){
            cd f=poly_eval(n,c,cur); cd fp=poly_deriv(n,c,cur);
            double fd=fp.r*fp.r+fp.i*fp.i; if(fd<1e-300)break;
            double st_r=(f.r*fp.r+f.i*fp.i)/fd, st_i=(f.i*fp.r-f.r*fp.i)/fd;
            if(!isfinite(st_r)||!isfinite(st_i))break;
            cur.r-=st_r; cur.i-=st_i;
            if(sqrt(st_r*st_r+st_i*st_i)<=1e-15*(sqrt(cur.r*cur.r+cur.i*cur.i)+1e-300))break;
        }
        z[i]=cur;
        cd fv=poly_eval(n,c,z[i]);
        if(fv.r*fv.r+fv.i*fv.i > 1e-26*scale*scale) return 0;
    }
    for(int i=0;i<n;i++)for(int j=i+1;j<n;j++){
        double dr=z[i].r-z[j].r, di=z[i].i-z[j].i;
        if(sqrt(dr*dr+di*di) < 1e-6*fmax(1.0,fmax(cd_abs(z[i]),cd_abs(z[j])))) return 0;
    }
    cd p={1.0,0.0}; for(int i=0;i<n;i++)p=cd_mul(p,z[i]);
    double cn=(n&1)?-c[n]:c[n];
    if(fabs(cd_abs(p)-fabs(cn)) > 1e-6*fmax(1.0,fabs(cn))) return 0;
    return 1;
}

/* Newton + deflation: find one root at a time */
static int newton_deflate(int n, const double c[], double R, double scale, cd roots[]){
    double coef[MAXN+1];
    for(int k=0;k<=n;k++) coef[k]=c[k];
    coef[0]=1.0;
    for(int k=0;k<n;k++){
        int deg = n-k;
        int found=0;
        for(int attempt=0; attempt<2*n && !found; attempt++){
            double ang = 2.0*M_PI*((double)attempt+0.5)/(double)n + 0.3*M_PI*((double)k/(double)n);
            cd cur={R*cos(ang), R*sin(ang)};
            for(int it=0;it<40;it++){
                cd f={1.0,0.0};
                for(int j=1;j<=deg;j++){ f=cd_mul(f,cur); f.r+=coef[j]; }
                cd fp={0.0,0.0};
                for(int j=0;j<=deg-1;j++){ double cf=(double)(deg-j)*(j==0?1.0:coef[j]); fp=cd_mul(fp,cur); fp.r+=cf; }
                double fd=fp.r*fp.r+fp.i*fp.i; if(fd<1e-300)break;
                double st_r=(f.r*fp.r+f.i*fp.i)/fd, st_i=(f.i*fp.r-f.r*fp.i)/fd;
                if(!isfinite(st_r)||!isfinite(st_i))break;
                cur.r-=st_r; cur.i-=st_i;
                if(sqrt(st_r*st_r+st_i*st_i)<=1e-15*(sqrt(cur.r*cur.r+cur.i*cur.i)+1e-300))break;
            }
            cd f={1.0,0.0};
            for(int j=1;j<=deg;j++){ f=cd_mul(f,cur); f.r+=coef[j]; }
            if(f.r*f.r+f.i*f.i > 1e-24*scale*scale) continue;
            int dup=0;
            for(int q=0;q<k;q++){
                double dr=cur.r-roots[q].r, di=cur.i-roots[q].i;
                if(sqrt(dr*dr+di*di) < 1e-5*fmax(1.0,fmax(cd_abs(cur),cd_abs(roots[q])))){ dup=1; break; }
            }
            if(dup) continue;
            roots[k]=cur;
            /* deflate: coef = (z - cur) * q, q monic degree deg-1 */
            cd q[MAXN+1];
            q[0].r=1.0; q[0].i=0.0;
            int okq=1;
            for(int j=1;j<=deg;j++){
                q[j].r = coef[j] - q[j-1].r*cur.r + q[j-1].i*cur.i;
                q[j].i = -q[j-1].i*cur.r - q[j-1].r*cur.i;
            }
            double rem_r = coef[deg] - (q[deg-1].r*cur.r - q[deg-1].i*cur.i);
            double rem_i = 0.0 - (q[deg-1].i*cur.r + q[deg-1].r*cur.i);
            if(rem_r*rem_r+rem_i*rem_i > 1e-20*scale*scale) okq=0;
            for(int j=0;j<deg;j++)
                if(fabs(q[j].i) > 1e-10*fmax(1.0,fabs(q[j].r))) okq=0;
            if(!okq) continue;
            coef[0]=1.0;
            for(int j=1;j<deg;j++) coef[j]=q[j].r;
            found=1;
        }
        if(!found) return 0;
    }
    return 1;
}

int main(void){
    for (int n = 3; n <= 10; n++) {
        int failA=0, failB=0, failC=0, tot=2000;
        for(int t=0;t<tot;t++){
            srand(777 + t*31 + n);
            double A[MAXN*MAXN]; for(int i=0;i<n*n;i++) A[i]=((double)rand()/RAND_MAX)*4.0-2.0;
            double P[MAXN*MAXN], Q[MAXN*MAXN], p[MAXN+1];
            for(int i=0;i<n;i++)for(int j=0;j<n;j++)P[i*n+j]=(i==j)?1.0:0.0;
            p[0]=n;
            for(int k=1;k<=n;k++){
                for(int i=0;i<n;i++)for(int j=0;j<n;j++)Q[i*n+j]=0.0;
                for(int i=0;i<n;i++)for(int tt=0;tt<n;tt++){ double at=A[i*n+tt]; if(at==0.0)continue;
                    for(int j=0;j<n;j++)Q[i*n+j]+=at*P[tt*n+j]; }
                for(int i=0;i<n;i++)for(int j=0;j<n;j++)P[i*n+j]=Q[i*n+j];
                double tr=0; for(int i=0;i<n;i++)tr+=P[i*n+i]; p[k]=tr;
            }
            double e[MAXN+1], c[MAXN+1]; e[0]=1.0;
            for(int k=1;k<=n;k++){ double s=0; for(int i=1;i<=k;i++){ double sgn=(i&1)?1.0:-1.0; s+=sgn*e[k-i]*p[i]; } e[k]=s/k; }
            c[0]=1.0; for(int k=1;k<=n;k++)c[k]=((k&1)?-1.0:1.0)*e[k];
            double R=0;
            for(int i=0;i<n;i++){ double s=fabs(A[i*n+i]); for(int j=0;j<n;j++)if(j!=i)s+=fabs(A[i*n+j]); if(s>R)R=s; }
            if(R<1e-8)R=1e-8;
            double scale=0; for(int k=0;k<=n;k++){ double ck=(k==0)?1.0:c[k]; double pw=1; for(int tt=0;tt<n-k;tt++)pw*=R; scale+=fabs(ck)*pw; }
            cd zA[MAXN];
            for(int i=0;i<n;i++){ double ang=2*M_PI*((double)i+0.5)/n + 1e-6*((double)i-0.5*(n-1)); zA[i].r=R*cos(ang); zA[i].i=R*sin(ang); }
            int okA = (dk_run(n,c,zA,100,scale)>0) && polish_all(n,c,zA,scale);
            cd zB[MAXN];
            for(int i=0;i<n;i++){ double ang=2*M_PI*((double)i+0.5)/n; double rr=R*(1.0+0.4*((double)i/(double)(n-1)-0.5)); zB[i].r=rr*cos(ang); zB[i].i=rr*sin(ang); }
            int okB = (dk_run(n,c,zB,100,scale)>0) && polish_all(n,c,zB,scale);
            cd zC[MAXN];
            int okC = newton_deflate(n,c,R,scale,zC);
            if(!okA)failA++; if(!okB)failB++; if(!okC)failC++;
        }
        printf("n=%2d: failA(tiny shear)=%3d  failB(radius ramp)=%3d  failC(newton-deflate)=%3d   of %d\n", n, failA, failB, failC, tot);
    }
    return 0;
}

