/* Eigenvector for complex eigenvalue l = a + b i (b != 0).
 * Null space of  [A-aI,  bI; -bI, A-aI]  is 2-dim; any nonzero vector
 * [u; v] in it gives eigenvector u + i v. */
static int eigvec_complex(int n, const double a[], double ar, double ai, double vr[], double vi[]) {
    int m = 2 * n;
    double M[2 * MAXN * 2 * MAXN];
    int piv[2 * MAXN];
    double x[2 * MAXN], xbest[2 * MAXN];
    double eps = 1e-7 * fmax(1.0, sqrt(ar * ar + ai * ai));
    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++) {
            M[i * m + j] = a[i * n + j] - ((i == j) ? ar : 0.0);
            M[i * m + j + n] = ((i == j) ? ai : 0.0);
            M[(i + n) * m + j] = -((i == j) ? ai : 0.0);
            M[(i + n) * m + j + n] = a[i * n + j] - ((i == j) ? ar : 0.0);
        }
    for (int i = 0; i < m; i++) M[i * m + i] += eps;
    if (!lu_factor(M, m, piv)) return 0;
    double bestnm = 0.0;
    for (int s = 0; s < m; s++) {
        for (int i = 0; i < m; i++) x[i] = (i == s) ? 1.0 : 0.0;
        lu_solve(M, m, piv, x, x);
        double nm2 = 0.0;
        for (int i = 0; i < m; i++) nm2 += x[i] * x[i];
        if (!isfinite(nm2)) return 0;
        if (nm2 > bestnm) {
            bestnm = nm2;
            for (int i = 0; i < m; i++) xbest[i] = x[i];
        }
    }
    if (bestnm < 1e-200) return 0;
    double inv = 1.0 / sqrt(bestnm);
    for (int i = 0; i < m; i++) xbest[i] *= inv;
    for (int it = 0; it < 3; it++) {
        lu_solve(M, m, piv, xbest, x);
        double nm2 = 0.0;
        for (int i = 0; i < m; i++) nm2 += x[i] * x[i];
        if (!isfinite(nm2) || nm2 < 1e-200) return 0;
        inv = 1.0 / sqrt(nm2);
        for (int i = 0; i < m; i++) xbest[i] = x[i] * inv;
    }
    for (int i = 0; i < n; i++) { vr[i] = xbest[i]; vi[i] = xbest[i + n]; }
    return 1;
}

/*
 * Main entry point.
 *   n        : matrix size (1..10)
 *   a        : input matrix, row-major n x n, float64
 *   lam_out  : 2 doubles (re, im) of the dominant eigenvalue
 *   vec_out  : 2n doubles (re part n, then im part n) of the eigenvector
 * Returns 1 on success (residual verified), 0 on any failure.
 */
int fast_dominant_eig(int n, const double a[], double lam_out[], double vec_out[]) {
    if (n < 1 || n > MAXN) return 0;
    for (int i = 0; i < n * n; i++)
        if (!isfinite(a[i])) return 0;

    if (n == 1) {
        lam_out[0] = a[0]; lam_out[1] = 0.0;
        vec_out[0] = 1.0; vec_out[1] = 0.0;
        return 1;
    }

    /* n == 2: closed form via trace and determinant */
    if (n == 2) {
        double tr = a[0 * 2 + 0] + a[1 * 2 + 1];
        double det = a[0 * 2 + 0] * a[1 * 2 + 1] - a[0 * 2 + 1] * a[1 * 2 + 0];
        double disc = tr * tr - 4.0 * det;
        cd lam;
        if (disc >= 0.0) {
            double s = sqrt(disc);
            /* choose the root with larger magnitude */
            double p = 0.5 * (tr + s), m = 0.5 * (tr - s);
            lam.r = (fabs(p) >= fabs(m)) ? p : m;
            lam.i = 0.0;
        } else {
            lam.r = 0.5 * tr;
            lam.i = 0.5 * sqrt(-disc);
        }
        if (!isfinite(lam.r) || !isfinite(lam.i)) return 0;
        double vr[MAXN], vi[MAXN];
        int ok = (fabs(lam.i) > 1e-12 * fmax(1.0, fabs(lam.r)))
                   ? eigvec_complex(2, a, lam.r, lam.i, vr, vi)
                   : (eigvec_real(2, a, lam.r, vr),
                      (vi[0] = 0.0, vi[1] = 0.0, 1));
        if (!ok) return 0;
        double r2 = 0.0, vn2 = 0.0;
        for (int i = 0; i < 2; i++) {
            vn2 += vr[i] * vr[i] + vi[i] * vi[i];
            double sr = -lam.r * vr[i] + lam.i * vi[i];
            double si = -lam.r * vi[i] - lam.i * vr[i];
            for (int j = 0; j < 2; j++) {
                sr += a[i * 2 + j] * vr[j];
                si += a[i * 2 + j] * vi[j];
            }
            r2 += sr * sr + si * si;
        }
        if (!isfinite(r2) || vn2 < 1e-16) return 0;
        double thr = 1e-6 * sqrt(lam.r * lam.r + lam.i * lam.i + 1.0) * sqrt(vn2);
        if (sqrt(r2) > thr) return 0;
        double inv = 1.0 / sqrt(vn2);
        for (int i = 0; i < 2; i++) { vr[i] *= inv; vi[i] *= inv; }
        lam_out[0] = lam.r; lam_out[1] = lam.i;
        for (int i = 0; i < 2; i++) { vec_out[i] = vr[i]; vec_out[2 + i] = vi[i]; }
        return 1;
    }

    /* ---- 1. power sums p_k = tr(A^k) ---- */
    double P[MAXN * MAXN], Q[MAXN * MAXN];
    double p[MAXN + 1];
    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++)
            P[i * n + j] = (i == j) ? 1.0 : 0.0;
