    double e[MAXN + 1], c[MAXN + 1];
    e[0] = 1.0;
    for (int k = 1; k <= n; k++) {
        double s = 0.0;
        for (int i = 1; i <= k; i++) {
            double sgn = (i & 1) ? 1.0 : -1.0;   /* (-1)^(i-1) */
            s += sgn * e[k - i] * p[i];
        }
        e[k] = s / (double)k;
    }
    c[0] = 1.0;
    for (int k = 1; k <= n; k++)
        c[k] = ((k & 1) ? -1.0 : 1.0) * e[k];    /* c_k = (-1)^k e_k */
    for (int k = 0; k <= n; k++)
        if (!isfinite(c[k])) return 0;

    /* ---- 3. Gershgorin radius (bounds |lambda| for all eigenvalues) ---- */
    double R = 0.0;
    for (int i = 0; i < n; i++) {
        double s = fabs(a[i * n + i]);
