#if HAVE_AVX512
/* Durand-Kerner vectorized over the n <= 10 roots with AVX-512.
 * Roots live in 16 lanes across two zmm registers (lo: 0..7, hi: 8..15,
 * unused lanes zero-padded); all results are masked to valid lanes. */
static int durand_kerner_avx(int n, const double c[], cd z[], int maxit, double scale) {
    double re[16], im[16];
    for (int i = 0; i < n; i++) { re[i] = z[i].r; im[i] = z[i].i; }
    for (int i = n; i < 16; i++) { re[i] = 0.0; im[i] = 0.0; }

    int mask_lo = (n > 8) ? 0xFF : ((1 << n) - 1);
    int mask_hi = (n > 8) ? ((1 << (n - 8)) - 1) : 0;

    __m512d zr_lo = _mm512_loadu_pd(re);
    __m512d zr_hi = _mm512_loadu_pd(re + 8);
    __m512d zi_lo = _mm512_loadu_pd(im);
    __m512d zi_hi = _mm512_loadu_pd(im + 8);

    const double brk = 1e-12;

    for (int it = 0; it < maxit; it++) {
        /* ---- f = p(z) via complex Horner, elementwise ---- */
        __m512d fr_lo = _mm512_set1_pd(1.0), fi_lo = _mm512_set1_pd(0.0);
        __m512d fr_hi = _mm512_set1_pd(1.0), fi_hi = _mm512_set1_pd(0.0);
        for (int k = 1; k <= n; k++) {
            double ck = c[k];
            __m512d nfr = _mm512_sub_pd(_mm512_mul_pd(fr_lo, zr_lo), _mm512_mul_pd(fi_lo, zi_lo));
            __m512d nfi = _mm512_fmadd_pd(fr_lo, zi_lo, _mm512_mul_pd(fi_lo, zr_lo));
            fr_lo = _mm512_add_pd(nfr, _mm512_set1_pd(ck));
            fi_lo = nfi;
            if (mask_hi) {
                nfr = _mm512_sub_pd(_mm512_mul_pd(fr_hi, zr_hi), _mm512_mul_pd(fi_hi, zi_hi));
                nfi = _mm512_fmadd_pd(fr_hi, zi_hi, _mm512_mul_pd(fi_hi, zr_hi));
                fr_hi = _mm512_add_pd(nfr, _mm512_set1_pd(ck));
                fi_hi = nfi;
            }
        }

        /* ---- prod_i = prod_{j != i} (z_i - z_j), elementwise ---- */
        __m512d pr_lo = _mm512_set1_pd(1.0), pi_lo = _mm512_set1_pd(0.0);
        __m512d pr_hi = _mm512_set1_pd(1.0), pi_hi = _mm512_set1_pd(0.0);
        for (int j = 0; j < n; j++) {
            double jr = re[j], ji = im[j];
            int m_lo = (j < 8) ? (mask_lo & ~(1 << j)) : mask_lo;
            int m_hi = (j >= 8) ? (mask_hi & ~(1 << (j - 8))) : mask_hi;
            __m512d dr_lo = _mm512_sub_pd(zr_lo, _mm512_set1_pd(jr));
            __m512d di_lo = _mm512_sub_pd(zi_lo, _mm512_set1_pd(ji));
            __m512d npr = _mm512_sub_pd(_mm512_mul_pd(pr_lo, dr_lo), _mm512_mul_pd(pi_lo, di_lo));
            __m512d npi = _mm512_fmadd_pd(pr_lo, di_lo, _mm512_mul_pd(pi_lo, dr_lo));
            pr_lo = _mm512_mask_mov_pd(pr_lo, m_lo, npr);
            pi_lo = _mm512_mask_mov_pd(pi_lo, m_lo, npi);
            if (mask_hi) {
                __m512d dr_hi = _mm512_sub_pd(zr_hi, _mm512_set1_pd(jr));
                __m512d di_hi = _mm512_sub_pd(zi_hi, _mm512_set1_pd(ji));
                npr = _mm512_sub_pd(_mm512_mul_pd(pr_hi, dr_hi), _mm512_mul_pd(pi_hi, di_hi));
                npi = _mm512_fmadd_pd(pr_hi, di_hi, _mm512_mul_pd(pi_hi, dr_hi));
                pr_hi = _mm512_mask_mov_pd(pr_hi, m_hi, npr);
                pi_hi = _mm512_mask_mov_pd(pi_hi, m_hi, npi);
            }
        }

        /* ---- step = f / prod; reject near-collisions (|prod|^2 too small) ---- */
        __m512d pd_lo = _mm512_add_pd(_mm512_mul_pd(pr_lo, pr_lo), _mm512_mul_pd(pi_lo, pi_lo));
        __m512d pd_hi = _mm512_add_pd(_mm512_mul_pd(pr_hi, pr_hi), _mm512_mul_pd(pi_hi, pi_hi));
        __mmask16 bad_lo = _mm512_mask_cmplt_pd_mask(mask_lo, pd_lo, _mm512_set1_pd(1e-24));
        __mmask16 bad_hi = _mm512_mask_cmplt_pd_mask(mask_hi, pd_hi, _mm512_set1_pd(1e-24));
        if (bad_lo | bad_hi) return 0;

        __m512d sr_lo = _mm512_div_pd(_mm512_fmadd_pd(fr_lo, pr_lo, _mm512_mul_pd(fi_lo, pi_lo)), pd_lo);
        __m512d si_lo = _mm512_div_pd(_mm512_fnmsub_pd(fr_lo, pi_lo, _mm512_mul_pd(fi_lo, pr_lo)), pd_lo);
        __m512d sr_hi = _mm512_setzero_pd(), si_hi = _mm512_setzero_pd();
        if (mask_hi) {
            sr_hi = _mm512_div_pd(_mm512_fmadd_pd(fr_hi, pr_hi, _mm512_mul_pd(fi_hi, pi_hi)), pd_hi);
            si_hi = _mm512_div_pd(_mm512_fnmsub_pd(fr_hi, pi_hi, _mm512_mul_pd(fi_hi, pr_hi)), pd_hi);
        }

        /* ---- z -= step; measure max step over valid lanes ---- */
        zr_lo = _mm512_sub_pd(zr_lo, sr_lo);
        zi_lo = _mm512_sub_pd(zi_lo, si_lo);
        if (mask_hi) {
            zr_hi = _mm512_sub_pd(zr_hi, sr_hi);
            zi_hi = _mm512_sub_pd(zi_hi, si_hi);
        }
        __m512d ch_lo = _mm512_sqrt_pd(_mm512_add_pd(_mm512_mul_pd(sr_lo, sr_lo), _mm512_mul_pd(si_lo, si_lo)));
        double maxch = _mm512_reduce_max_pd(_mm512_mask_max_pd(_mm512_setzero_pd(), mask_lo, ch_lo, _mm512_setzero_pd()));
        if (mask_hi) {
            __m512d ch_hi = _mm512_sqrt_pd(_mm512_add_pd(_mm512_mul_pd(sr_hi, sr_hi), _mm512_mul_pd(si_hi, si_hi)));
            double mh = _mm512_reduce_max_pd(_mm512_mask_max_pd(_mm512_setzero_pd(), mask_hi, ch_hi, _mm512_setzero_pd()));
            if (mh > maxch) maxch = mh;
        }
        if (maxch < brk * scale) break;
    }

    _mm512_storeu_pd(re, zr_lo);
    _mm512_storeu_pd(re + 8, zr_hi);
    _mm512_storeu_pd(im, zi_lo);
    _mm512_storeu_pd(im + 8, zi_hi);
    for (int i = 0; i < n; i++) {
        if (!isfinite(re[i]) || !isfinite(im[i])) return 0;
        z[i].r = re[i];
        z[i].i = im[i];
    }
    return 1;
}
#endif

/* Newton polish of one root; returns 1 if residual check passes. */
static int newton_polish(int n, const double c[], cd *z, double scale) {
    cd cur = *z;
    for (int it = 0; it < 12; it++) {
        cd f = poly_eval(n, c, cur);
        cd fp = poly_deriv(n, c, cur);
        double fd = fp.r * fp.r + fp.i * fp.i;
        if (fd < 1e-300) break;
        double st_r = (f.r * fp.r + f.i * fp.i) / fd;
        double st_i = (f.i * fp.r - f.r * fp.i) / fd;
        if (!isfinite(st_r) || !isfinite(st_i)) break;
        double nr = cur.r - st_r;
        double ni = cur.i - st_i;
        if (!isfinite(nr) || !isfinite(ni)) break;
        cur.r = nr; cur.i = ni;
        if (sqrt(st_r * st_r + st_i * st_i) <= 1e-15 * (sqrt(nr * nr + ni * ni) + 1e-300))
            break;
    }
…
}

