/*
 * Eigenvector for complex lambda = a + b i (b > 0) via inverse iteration on
 * the factored 2n x 2n system M22 = [[A-aI, bI], [-bI, A-aI]] + eps I.
 * Every real null vector (u, w) corresponds to the eigenvector v = u + i w.
 * vr = u, vi = w on return.
 */
static int eigvec_m22(int n, const double a[], double ar, double ai,
                      const double M[], const int piv[],
                      int attempt, double vr[], double vi[]) {
    int n2 = 2 * n;
    double x[2 * MAXN], x2[2 * MAXN];
    double seed = 26699.0 * (attempt + 1) + 13.7 * ar + 7.31 * ai + 5.17;
    for (int i = 0; i < n2; i++) {
        seed = fmod(seed * 16807.0, 2147483647.0);
        x[i] = seed / 2147483647.0 * 2.0 - 1.0;
    }
    double nm2 = 0.0;
    for (int i = 0; i < n2; i++) nm2 += x[i] * x[i];
    double inv = 1.0 / sqrt(nm2);
    for (int i = 0; i < n2; i++) x[i] *= inv;
    for (int s = 0; s < 2; s++) {
        lu_solve(M, n2, piv, x, x2);
        nm2 = 0.0;
        for (int i = 0; i < n2; i++) nm2 += x2[i] * x2[i];
        if (!isfinite(nm2) || nm2 < 1e-300) {
            for (int i = 0; i < n2; i++) x[i] = 0.0;
            x[(attempt * 3 + 1) % n2] = 1.0;
            break;
        }
        inv = 1.0 / sqrt(nm2);
        for (int i = 0; i < n2; i++) x[i] = x2[i] * inv;
    }
    for (int i = 0; i < n; i++) { vr[i] = x[i]; vi[i] = x[i + n]; }
    return 1;
}
