/* Durand-Kerner simultaneous iteration (scalar fallback / small n).
 * z[] (n entries) in/out. Returns 1 if it finished without pathology. */
static int durand_kerner_scalar(int n, const double c[], cd z[], int maxit, double scale) {
    double brk = 1e-12;
    for (int it = 0; it < maxit; it++) {
        cd zn[MAXN];
        double maxch = 0.0;
        for (int i = 0; i < n; i++) {
            cd f = poly_eval(n, c, z[i]);
            cd prod;
            prod.r = 1.0; prod.i = 0.0;
            for (int j = 0; j < n; j++) {
                if (j == i) continue;
                cd d;
                d.r = z[i].r - z[j].r;
                d.i = z[i].i - z[j].i;
                prod = cd_mul(prod, d);
            }
            double pd = prod.r * prod.r + prod.i * prod.i;
            if (pd < 1e-24) return 0;          /* two iterates collided */
            double st_r = (f.r * prod.r + f.i * prod.i) / pd;
            double st_i = (f.i * prod.r - f.r * prod.i) / pd;
            if (!isfinite(st_r) || !isfinite(st_i)) return 0;
            double zr = z[i].r - st_r;
            double zi = z[i].i - st_i;
            if (!isfinite(zr) || !isfinite(zi)) return 0;
            double ch = sqrt(st_r * st_r + st_i * st_i);
            if (ch > maxch) maxch = ch;
            zn[i].r = zr; zn[i].i = zi;
        }
        for (int i = 0; i < n; i++) z[i] = zn[i];
        if (maxch < brk * scale) break;
    }
    return 1;
}

