```c
/*
 * Build the eigenvector linear system into M (row-major, stride n2) and
 * return n2:
 *   real lambda (b == 0):
 *       n2 = n,   M = (A - aI)^2 + eps I
 *       (real nullspace = span{v_lambda} for a simple eigenvalue)
 *   complex lambda (b > 0):
 *       n2 = 2n,  M = [[A - aI, b I], [-b I, A - aI]] + eps I
 *       (any real null vector (u,w) is v = u + i w, an eigenvector for
 *        a + b i:  (A - lambda)(u + iw) = 0  <=>  the two block equations)
 */
static int build_eigsys(int n, const double a[], double ar, double ai,
                        double M[], double eps) {
    if (ai <= 1e-12) {
        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++) {
                double s = 0.0;
                for (int t = 0; t < n; t++)
                    s += (a[i * n + t] - (i == t ? ar : 0.0)) *
                         (a[t * n + j] - (t == j ? ar : 0.0));
                M[i * n + j] = s;
            }
        for (int i = 0; i < n; i++) M[i * n + i] += eps;
        return n;
    }
    int n2 = 2 * n;
    for (int i = 0; i < n2; i++)
        for (int j = 0; j < n2; j++) {
            double v;
            if (i < n && j < n)
                v = a[i * n + j] - (i == j ? ar : 0.0);
            else if (i >= n && j >= n)
                v = a[i - n + (j - n)] - (i == j ? ar : 0.0);
            else if (j - n == i)
                v = ai;
            else if (i - n == j)
                v = -ai;
            else
                v = 0.0;
            M[i * n2 + j] = v;
        }
    for (int i = 0; i < n2; i++) M[i * n2 + i] += eps;
    return n2;
}

/*
 * Eigenvector for a complex lambda via inverse iteration on the factored
 * 2n x 2n system from build_eigsys. Two solves from a deterministic start;
 * on return vr = u, vi = w (v = u + i w is an eigenvector for lambda).
 */
static int eigvec_m22(int n, const double a[], double ar, double ai,
                      const double M[], const int piv[],
                      int attempt, double vr[], double vi[]) {
    int n2 = 2 * n;
    double x[2 * MAXN], x2[2 * MAXN];
    double seed = 26699.0 * (attempt + 1) + 13.7 * ar + 7.31 * ai + 5.17;
    for (int i = 0; i < n2; i++) {
        seed = fmod(seed * 16807.0, 2147483647.0);
        x[i] = seed / 2147483647.0 * 2.0 - 1.0;
    }
    double nm2 = 0.0;
    for (int i = 0; i < n2; i++) nm2 += x[i] * x[i];
    double inv = 1.0 / sqrt(nm2);
    for (int i = 0; i < n2; i++) x[i] *= inv;
    for (int s = 0; s < 2; s++) {
        lu_solve(M, n2, piv, x, x2);
        nm2 = 0.0;
        for (int i = 0; i < n2; i++) nm2 += x2[i] * x2[i];
        if (!isfinite(nm2) || nm2 < 1e-300) {
            for (int i = 0; i < n2; i++) x[i] = 0.0;
            x[(attempt * 3 + 1) % n2] = 1.0;
            break;
        }
        inv = 1.0 / sqrt(nm2);
        for (int i = 0; i < n2; i++) x[i] = x2[i] * inv;
    }
    for (int i = 0; i < n; i++) { vr[i] = x[i]; vi[i] = x[i + n]; }
    return 1;
}
