        __m512d pd_lo = _mm512_add_pd(_mm512_mul_pd(pr_lo, pr_lo), _mm512_mul_pd(pi_lo, pi_lo));
        __m512d pd_hi = _mm512_add_pd(_mm512_mul_pd(pr_hi, pr_hi), _mm512_mul_pd(pi_hi, pi_hi));
