typedef struct { double r, i; } cd;

static inline cd cd_mul(cd a, cd b) {
    cd c;
    c.r = a.r * b.r - a.i * b.i;
    c.i = a.r * b.i + a.i * b.r;
    return c;
}

static inline double cd_abs(cd a) { return sqrt(a.r * a.r + a.i * a.i); }

/* p(z) = z^n + c1 z^{n-1} + ... + c_n  (Horner) */
static cd poly_eval(int n, const double c[], cd z) {
    cd res;
    res.r = 1.0; res.i = 0.0;
    for (int k = 1; k <= n; k++) {
        res = cd_mul(res, z);
        res.r += c[k];
